"use client";

export { default as ImageEditor } from "./ImageEditor";
export type {
  EditorObject,
  EditorObjectType,
  ExportOptions,
  ImageEditorCanvas,
  ImageEditorDocument,
  ImageEditorErrorCode,
  ImageEditorHandle,
  ImageEditorProps,
  ImageEditorState,
  ImageEditorTool,
} from "./ImageEditor.types";
export { ImageEditorError } from "./ImageEditor.types";

import { Button } from "../motion/button/base";
import { Check, FolderOpen, Layers3, Shapes, Type, X } from "lucide-react";
import {
  forwardRef,
  useImperativeHandle,
  useRef,
} from "react";
import type { ImageEditorHandle, ImageEditorProps } from "./ImageEditor.types";
import { useEditorKeyboard } from "./hooks/useEditorKeyboard";
import { useImageEditorController } from "./hooks/useImageEditorController";
import LayersPanel from "./panels/LayersPanel";
import BottomToolbar from "./toolbars/BottomToolbar";
import PaintToolbar from "./toolbars/PaintToolbar";
import SelectionToolbar from "./toolbars/SelectionToolbar";
import TopToolbar from "./toolbars/TopToolbar";
import "./ImageEditor.css";

const ImageEditor = forwardRef<ImageEditorHandle, ImageEditorProps>(function ImageEditor(
  props,
  ref,
) {
  const rootRef = useRef<HTMLElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cropPointerRef = useRef<{ x: number; y: number } | null>(null);
  const controller = useImageEditorController(props);
  const { actions, document: editorDocument, state } = controller;
  useEditorKeyboard(rootRef, controller.canvas, actions);

  useImperativeHandle(
    ref,
    () => ({
      addImage: actions.addImage,
      addText: actions.addText,
      loadDocument: actions.loadDocument,
      getDocument: () => structuredClone(editorDocument),
      undo: actions.undo,
      redo: actions.redo,
      fitToViewport: actions.fitToViewport,
      exportImage: actions.exportImage,
    }),
    [actions, editorDocument],
  );

  const importFiles = (files: FileList | File[]) => {
    const file = files[0];
    if (file) void actions.addImage(file);
  };

  const toggleFullscreen = async () => {
    const root = rootRef.current;
    if (!root) return;
    if (globalThis.document.fullscreenElement) await globalThis.document.exitFullscreen();
    else await root.requestFullscreen();
  };

  return (
    <section
      ref={rootRef}
      className={["image-editor", props.className].filter(Boolean).join(" ")}
      style={props.style}
      role="application"
      aria-label="图片编辑器"
      tabIndex={-1}
    >
      <TopToolbar document={controller.document} actions={actions} onClose={props.onClose} />
      <aside className="image-editor__left-rail" aria-label="素材和图层">
        <Button variant="ghost" size="icon" type="button" aria-label="图片素材" title="图片素材" onClick={() => fileInputRef.current?.click()}><FolderOpen size={21} /></Button>
        <Button variant="ghost" size="icon" type="button" aria-label="图层面板" title="图层面板" onClick={actions.toggleLayers}><Layers3 size={21} /></Button>
        <Button variant="ghost" size="icon" type="button" aria-label="添加图形" title="添加图形" onClick={actions.addRect}><Shapes size={21} /></Button>
        <Button variant="ghost" size="icon" type="button" aria-label="添加文本图层" title="添加文本图层" onClick={() => actions.addText()}><Type size={21} /></Button>
      </aside>
      <LayersPanel
        open={state.layersOpen}
        document={controller.document}
        selectedIds={state.selectedIds}
        actions={actions}
      />
      <main
        ref={controller.viewportRef}
        className="image-editor__workspace"
        data-testid="image-editor-workspace"
        tabIndex={0}
        onDragOver={(event) => event.preventDefault()}
        onDrop={(event) => {
          event.preventDefault();
          importFiles(event.dataTransfer.files);
        }}
        onPaste={(event) => {
          const file = [...event.clipboardData.items]
            .find((item) => item.kind === "file")
            ?.getAsFile();
          if (file) void actions.addImage(file);
        }}
        onPointerDown={(event) => {
          if (state.activeTool === "crop") {
            cropPointerRef.current = { x: event.clientX, y: event.clientY };
            event.currentTarget.setPointerCapture?.(event.pointerId);
          }
        }}
        onPointerMove={(event) => {
          const last = cropPointerRef.current;
          if (!last || state.activeTool !== "crop") return;
          actions.panCrop(
            (event.clientX - last.x) / state.zoom,
            (event.clientY - last.y) / state.zoom,
          );
          cropPointerRef.current = { x: event.clientX, y: event.clientY };
        }}
        onPointerUp={() => {
          cropPointerRef.current = null;
        }}
      >
        <div
          className="image-editor__canvas-stage"
          style={{
            width: controller.document.canvas.width,
            height: controller.document.canvas.height,
            transform: `scale(${state.zoom})`,
          }}
        >
          <canvas ref={controller.canvasElementRef} aria-label="编辑画布" />
        </div>
      </main>
      <SelectionToolbar selected={controller.selectedObjects} actions={actions} />
      {state.activeTool === "draw" ? <PaintToolbar state={state} actions={actions} /> : null}
      {state.activeTool === "crop" ? (
        <div className="image-editor__crop-toolbar" role="toolbar" aria-label="裁剪设置">
          <span>拖动图片调整裁剪区域</span>
          <Button variant="ghost" size="icon" type="button" aria-label="确认裁剪" onClick={actions.confirmCrop}><Check size={18} /></Button>
          <Button variant="ghost" size="icon" type="button" aria-label="取消裁剪" onClick={actions.cancelCrop}><X size={18} /></Button>
        </div>
      ) : null}
      <BottomToolbar
        state={state}
        actions={actions}
        onChooseImage={() => fileInputRef.current?.click()}
        onToggleFullscreen={() => void toggleFullscreen()}
      />
      <input
        ref={fileInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif"
        hidden
        onChange={(event) => {
          if (event.target.files) importFiles(event.target.files);
          event.target.value = "";
        }}
      />
      {state.isLoading ? <div className="image-editor__busy" role="status">正在处理…</div> : null}
      <div className="image-editor__announcer" aria-live="polite">
        {state.isDirty ? "画布已修改" : "画布已保存"}
      </div>
    </section>
  );
});

export default ImageEditor;

import type { CSSProperties } from "react";

export type EditorObjectType =
  | "image"
  | "text"
  | "rect"
  | "ellipse"
  | "line"
  | "arrow"
  | "drawing";

export type ImageEditorTool =
  | "select"
  | "rect"
  | "ellipse"
  | "line"
  | "arrow"
  | "draw"
  | "text"
  | "image"
  | "crop";

export type ImageEditorPaintMode = "brush" | "eraser";

export type ImageEditorCanvas = {
  width: number;
  height: number;
  background: string | null;
};

export type EditorObject = {
  id: string;
  type: EditorObjectType;
  name: string;
  locked: boolean;
  visible: boolean;
  fabricData: Record<string, unknown>;
};

export type ImageEditorDocument = {
  version: 1;
  canvas: ImageEditorCanvas;
  objects: EditorObject[];
};

export type ImageEditorState = {
  activeTool: ImageEditorTool;
  paintMode: ImageEditorPaintMode;
  drawColor: string;
  drawWidth: number;
  drawOpacity: number;
  selectedIds: string[];
  zoom: number;
  canUndo: boolean;
  canRedo: boolean;
  isDirty: boolean;
  isLoading: boolean;
  layersOpen: boolean;
};

export type ImageEditorErrorCode =
  | "UNSUPPORTED_FILE"
  | "FILE_TOO_LARGE"
  | "IMAGE_DECODE_FAILED"
  | "IMAGE_CORS_FAILED"
  | "DOCUMENT_INVALID"
  | "DOCUMENT_VERSION_UNSUPPORTED"
  | "STORAGE_FAILED"
  | "EXPORT_FAILED"
  | "EXPORT_CORS_FAILED"
  | "CANVAS_INIT_FAILED";

export class ImageEditorError extends Error {
  readonly code: ImageEditorErrorCode;
  readonly cause?: unknown;

  constructor(code: ImageEditorErrorCode, message: string, cause?: unknown) {
    super(message);
    this.name = "ImageEditorError";
    this.code = code;
    this.cause = cause;
  }
}

export type ExportOptions = {
  format?: "png" | "jpeg";
  quality?: number;
  transparent?: boolean;
  width?: number;
  height?: number;
  fileName?: string;
  download?: boolean;
};

export type ImageEditorProps = {
  className?: string;
  style?: CSSProperties;
  initialDocument?: ImageEditorDocument;
  storageKey?: string | false;
  maxImageSize?: number;
  historyLimit?: number;
  onChange?: (document: ImageEditorDocument) => void;
  onSelectionChange?: (objects: EditorObject[]) => void;
  onSave?: (document: ImageEditorDocument) => void;
  onExport?: (result: Blob) => void;
  onClose?: () => void;
  onError?: (error: ImageEditorError) => void;
};

export type ImageEditorHandle = {
  addImage(source: File | string): Promise<string>;
  addText(text?: string): string;
  loadDocument(document: ImageEditorDocument): Promise<void>;
  getDocument(): ImageEditorDocument;
  undo(): void;
  redo(): void;
  fitToViewport(): void;
  exportImage(options?: ExportOptions): Promise<Blob>;
};

import type { ImageEditorDocument } from "./ImageEditor.types";

export const DEFAULT_IMAGE_EDITOR_DOCUMENT: ImageEditorDocument = {
  version: 1,
  canvas: {
    width: 1024,
    height: 1024,
    background: "#ffffff",
  },
  objects: [],
};

export const DEFAULT_HISTORY_LIMIT = 50;
export const DEFAULT_MAX_IMAGE_SIZE = 15 * 1024 * 1024;

export const ASPECT_RATIO_OPTIONS = [
  { id: "custom", label: "custom", value: null },
  { id: "16:9", label: "16:9", value: 16 / 9 },
  { id: "9:16", label: "9:16", value: 9 / 16 },
  { id: "4:3", label: "4:3", value: 4 / 3 },
  { id: "3:4", label: "3:4", value: 3 / 4 },
  { id: "1:1", label: "1:1", value: 1 },
  { id: "3:2", label: "3:2", value: 3 / 2 },
  { id: "2:3", label: "2:3", value: 2 / 3 },
  { id: "7:4", label: "7:4", value: 7 / 4 },
  { id: "4:7", label: "4:7", value: 4 / 7 },
  { id: "21:9", label: "21:9", value: 21 / 9 },
] as const;

.image-editor {
  --editor-bg: #0b0b0d;
  --editor-surface: #27282d;
  --editor-surface-hover: #34363c;
  --editor-border: #41434a;
  --editor-text: #f5f5f6;
  --editor-muted: #a6a8af;
  --editor-accent: #2b9df4;
  position: relative;
  display: grid;
  grid-template-rows: 76px minmax(0, 1fr);
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  color: var(--editor-text);
  background: var(--editor-bg);
  font-family: "Geist Variable", sans-serif;
  outline: none;
}

.image-editor button,
.image-editor select,
.image-editor input {
  font: inherit;
}

.image-editor button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 40px;
  min-height: 40px;
  padding: 0 10px;
  color: var(--editor-text);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
}

.image-editor button:hover:not(:disabled) { background: var(--editor-surface-hover); }
.image-editor button:disabled { opacity: 0.36; cursor: not-allowed; }
.image-editor button.is-active { color: white; background: var(--editor-accent); }
.image-editor button:focus-visible,
.image-editor select:focus-visible,
.image-editor input:focus-visible { outline: 2px solid #8ecbff; outline-offset: 2px; }

.image-editor__topbar {
  position: relative;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 24px;
}

.image-editor__canvas-controls,
.image-editor__top-actions,
.image-editor__bottom-toolbar,
.image-editor__selection-toolbar,
.image-editor__crop-toolbar,
.image-editor__paint-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
}

.image-editor__canvas-controls select,
.image-editor__dimension,
.image-editor__color-control,
.image-editor__number-control {
  min-height: 44px;
  color: var(--editor-text);
  background: var(--editor-surface);
  border: 1px solid var(--editor-border);
  border-radius: 12px;
}

.image-editor__canvas-controls select { padding: 0 34px 0 14px; }
.image-editor__dimension { display: inline-flex; align-items: center; gap: 6px; padding: 0 10px; }
.image-editor__dimension span { color: var(--editor-muted); font-size: 12px; }
.image-editor__dimension input { width: 64px; color: var(--editor-text); background: transparent; border: 0; outline: 0; }
.image-editor__dimension-separator { color: var(--editor-muted); }
.image-editor__dimension-popover {
  position: absolute;
  z-index: 30;
  top: 66px;
  left: 150px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px;
  background: var(--editor-surface);
  border: 1px solid var(--editor-border);
  border-radius: 14px;
  box-shadow: 0 16px 40px rgb(0 0 0 / 0.35);
}
.image-editor__color-control { display: inline-grid; width: 44px; place-items: center; }
.image-editor__color-control input { width: 28px; height: 28px; padding: 0; border: 0; border-radius: 50%; overflow: hidden; }
.image-editor__text-button { border-color: var(--editor-border) !important; }

.image-editor__left-rail {
  position: absolute;
  z-index: 18;
  top: 50%;
  left: 24px;
  display: grid;
  gap: 4px;
  width: 72px;
  padding: 12px 8px;
  transform: translateY(-50%);
  background: var(--editor-surface);
  border: 1px solid var(--editor-border);
  border-radius: 28px;
}

.image-editor__left-rail button { min-height: 52px; }

.image-editor__workspace {
  position: relative;
  grid-row: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  box-sizing: border-box;
  padding-bottom: clamp(0px, 8vh, 80px);
  background-color: var(--editor-bg);
}

.image-editor__canvas-stage {
  position: relative;
  flex: 0 0 auto;
  transform-origin: center;
  background-color: white;
  box-shadow: 0 18px 60px rgb(0 0 0 / 0.42);
}

.image-editor__canvas-stage .canvas-container { width: 100% !important; height: 100% !important; }
.image-editor__canvas-stage canvas { display: block; }

.image-editor__bottom-toolbar,
.image-editor__selection-toolbar,
.image-editor__crop-toolbar,
.image-editor__paint-toolbar {
  position: absolute;
  z-index: 22;
  left: 50%;
  max-width: calc(100% - 220px);
  padding: 8px 10px;
  transform: translateX(-50%);
  overflow-x: auto;
  background: var(--editor-surface);
  border: 1px solid var(--editor-border);
  border-radius: 16px;
  box-shadow: 0 14px 40px rgb(0 0 0 / 0.28);
}

.image-editor__bottom-toolbar { bottom: clamp(24px, 10vh, 104px); }
.image-editor__selection-toolbar { top: 86px; }
.image-editor__paint-toolbar {
  top: 86px;
  min-width: 250px;
  justify-content: center;
  overflow: visible;
}
.image-editor__crop-toolbar { bottom: 86px; }
.image-editor__toolbar-divider { width: 1px; height: 32px; margin: 0 4px; flex: 0 0 auto; background: var(--editor-border); }
.image-editor__zoom-value { min-width: 48px; color: var(--editor-muted); font-size: 12px; text-align: center; }
.image-editor__paint-color {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 40px;
  color: var(--editor-text);
  cursor: pointer;
}
.image-editor__paint-color input {
  position: absolute;
  right: 2px;
  bottom: 0;
  width: 18px;
  height: 18px;
  padding: 0;
  overflow: hidden;
  background: transparent;
  border: 2px solid white;
  border-radius: 50%;
  cursor: pointer;
}
.image-editor__paint-settings {
  position: absolute;
  top: calc(100% + 10px);
  left: 50%;
  display: grid;
  width: 280px;
  box-sizing: border-box;
  gap: 18px;
  padding: 18px;
  transform: translateX(-50%);
  background: #34353c;
  border: 1px solid #4b4d55;
  border-radius: 16px;
  box-shadow: 0 18px 42px rgb(0 0 0 / 0.34);
}
.image-editor__paint-settings label {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px 12px;
  color: var(--editor-text);
  font-size: 14px;
  font-weight: 650;
}
.image-editor__paint-settings output {
  color: var(--editor-muted);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.image-editor__paint-settings input[type="range"] {
  grid-column: 1 / -1;
  width: 100%;
  min-height: 24px;
  margin: 0;
  accent-color: var(--editor-accent);
  cursor: pointer;
}

.image-editor__number-control { display: flex; flex: 0 0 auto; align-items: center; gap: 8px; padding: 0 10px; }
.image-editor__number-control span { flex: 0 0 auto; color: var(--editor-muted); font-size: 12px; white-space: nowrap; }
.image-editor__number-control input { width: 54px; color: var(--editor-text); background: transparent; border: 0; }

.image-editor__layers-panel {
  position: absolute;
  z-index: 19;
  top: 88px;
  bottom: 88px;
  left: 108px;
  width: 260px;
  padding: 14px;
  overflow: auto;
  background: var(--editor-surface);
  border: 1px solid var(--editor-border);
  border-radius: 16px;
  box-shadow: 0 20px 55px rgb(0 0 0 / 0.32);
}

.image-editor__panel-title { margin: 2px 4px 12px; font-size: 14px; font-weight: 650; }
.image-editor__layer-list { display: grid; gap: 6px; }
.image-editor__layer-list > div { display: grid; grid-template-columns: minmax(0, 1fr) 36px 36px; align-items: center; border: 1px solid transparent; border-radius: 10px; }
.image-editor__layer-list > div.is-selected { background: #343b47; border-color: #4b6e91; }
.image-editor__layer-name { justify-content: space-between !important; min-width: 0; }
.image-editor__layer-name span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.image-editor__layer-name small { color: var(--editor-muted); }
.image-editor__layer-list p { padding: 24px 8px; color: var(--editor-muted); font-size: 13px; line-height: 1.5; }

.image-editor__busy {
  position: absolute;
  z-index: 40;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgb(5 5 7 / 0.45);
  backdrop-filter: blur(2px);
}

.image-editor__announcer,
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 960px) {
  .image-editor { grid-template-rows: 64px minmax(0, 1fr); }
  .image-editor__topbar { padding: 10px 12px; }
  .image-editor__dimension,
  .image-editor__text-button { display: none; }
  .image-editor__left-rail { left: 12px; width: 58px; }
  .image-editor__bottom-toolbar,
  .image-editor__selection-toolbar { max-width: calc(100% - 96px); }
}

import type { FabricObject } from "fabric";
import {
  ImageEditorError,
  type EditorObject,
  type EditorObjectType,
  type ImageEditorCanvas,
  type ImageEditorDocument,
} from "../ImageEditor.types";
import {
  applyEditorLocked,
  SERIALIZED_EDITOR_PROPERTIES,
  type EditableFabricObject,
} from "../utils/editorObject";

const SUPPORTED_TYPES = new Set<EditorObjectType>([
  "image",
  "text",
  "rect",
  "ellipse",
  "line",
  "arrow",
  "drawing",
]);

type SerializableObject = {
  id: string;
  editorType: EditorObjectType;
  name: string;
  editorLocked?: boolean;
  visible?: boolean;
  toObject(properties?: readonly string[]): Record<string, unknown>;
};

type SerializableCanvas = {
  getObjects(): SerializableObject[];
};

type LoadableObject = SerializableObject & {
  set(options: Record<string, unknown>): unknown;
  setControlsVisibility?(options: Record<string, boolean>): unknown;
};

type LoadableCanvas = {
  backgroundColor: string;
  setDimensions(size: { width: number; height: number }): unknown;
  loadFromJSON(json: Record<string, unknown>): Promise<unknown>;
  getObjects(): LoadableObject[];
  requestRenderAll(): unknown;
};

function invalid(message: string): never {
  throw new ImageEditorError("DOCUMENT_INVALID", message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validateCanvas(value: unknown): asserts value is ImageEditorCanvas {
  if (!isRecord(value)) invalid("文档缺少有效画布信息");
  if (!Number.isFinite(value.width) || Number(value.width) <= 0) invalid("画布宽度无效");
  if (!Number.isFinite(value.height) || Number(value.height) <= 0) invalid("画布高度无效");
  if (value.background !== null && typeof value.background !== "string") {
    invalid("画布背景无效");
  }
}

function validateObject(value: unknown): asserts value is EditorObject {
  if (!isRecord(value)) invalid("对象数据无效");
  if (typeof value.id !== "string" || value.id.length === 0) invalid("对象 ID 无效");
  if (typeof value.type !== "string" || !SUPPORTED_TYPES.has(value.type as EditorObjectType)) {
    invalid("对象类型无效");
  }
  if (typeof value.name !== "string" || value.name.length === 0) invalid("对象名称无效");
  if (typeof value.locked !== "boolean") invalid("对象锁定状态无效");
  if (typeof value.visible !== "boolean") invalid("对象显示状态无效");
  if (!isRecord(value.fabricData)) invalid("Fabric 对象数据无效");
}

export function validateDocument(value: unknown): asserts value is ImageEditorDocument {
  if (!isRecord(value)) invalid("文档格式无效");
  if (value.version !== 1) {
    throw new ImageEditorError("DOCUMENT_VERSION_UNSUPPORTED", "不支持的文档版本");
  }
  validateCanvas(value.canvas);
  if (!Array.isArray(value.objects)) invalid("文档对象列表无效");
  const ids = new Set<string>();
  for (const object of value.objects) {
    validateObject(object);
    if (ids.has(object.id)) invalid("对象 ID 必须唯一");
    ids.add(object.id);
  }
}

export function serializeCanvas(
  canvas: SerializableCanvas,
  canvasState: ImageEditorCanvas,
): ImageEditorDocument {
  const objects = canvas.getObjects().map<EditorObject>((object) => {
    const fabricData = { ...object.toObject([...SERIALIZED_EDITOR_PROPERTIES]) };
    delete fabricData.id;
    delete fabricData.editorType;
    delete fabricData.name;
    delete fabricData.editorLocked;
    delete fabricData.visible;
    return {
      id: object.id,
      type: object.editorType,
      name: object.name,
      locked: Boolean(object.editorLocked),
      visible: object.visible !== false,
      fabricData,
    };
  });

  return {
    version: 1,
    canvas: { ...canvasState },
    objects,
  };
}

export async function loadDocumentIntoCanvas(
  canvas: LoadableCanvas,
  value: unknown,
): Promise<ImageEditorDocument> {
  validateDocument(value);
  const document = structuredClone(value);
  canvas.setDimensions({
    width: document.canvas.width,
    height: document.canvas.height,
  });
  canvas.backgroundColor = document.canvas.background ?? "rgba(0,0,0,0)";
  await canvas.loadFromJSON({
    version: "7.0.0",
    objects: document.objects.map((object) => ({
      ...object.fabricData,
      id: object.id,
      editorType: object.type,
      name: object.name,
      editorLocked: object.locked,
      visible: object.visible,
    })),
  });

  for (const object of canvas.getObjects()) {
    applyEditorLocked(object as unknown as EditableFabricObject, Boolean(object.editorLocked));
  }
  canvas.requestRenderAll();
  return document;
}

export function toEditableFabricObject(object: FabricObject): EditableFabricObject {
  return object as EditableFabricObject;
}

export class HistoryManager<T> {
  private readonly limit: number;
  private entries: T[] = [];
  private cursor = -1;

  constructor(limit: number) {
    this.limit = Math.max(1, Math.floor(limit));
  }

  get current(): T | null {
    return this.cursor < 0 ? null : structuredClone(this.entries[this.cursor]);
  }

  get canUndo() {
    return this.cursor > 0;
  }

  get canRedo() {
    return this.cursor >= 0 && this.cursor < this.entries.length - 1;
  }

  reset(value: T) {
    this.entries = [structuredClone(value)];
    this.cursor = 0;
  }

  commit(value: T) {
    const next = structuredClone(value);
    const current = this.entries[this.cursor];
    if (current !== undefined && JSON.stringify(current) === JSON.stringify(next)) return false;
    this.entries = this.entries.slice(0, this.cursor + 1);
    this.entries.push(next);
    if (this.entries.length > this.limit) {
      this.entries.splice(0, this.entries.length - this.limit);
    }
    this.cursor = this.entries.length - 1;
    return true;
  }

  undo(): T | null {
    if (!this.canUndo) return null;
    this.cursor -= 1;
    return structuredClone(this.entries[this.cursor]);
  }

  redo(): T | null {
    if (!this.canRedo) return null;
    this.cursor += 1;
    return structuredClone(this.entries[this.cursor]);
  }
}

import {
  Ellipse,
  Group,
  Line,
  Rect,
  Textbox,
  Triangle,
  type Canvas,
  type FabricObject,
} from "fabric";
import {
  applyEditorLocked,
  ensureEditorMetadata,
  type EditableFabricObject,
} from "../utils/editorObject";

function editable(object: FabricObject) {
  return object as EditableFabricObject;
}

type Point = { x: number; y: number };

export function createDirectionalArrow(
  start: Point,
  end: Point,
  color = "#ff2d20",
  strokeWidth = 6,
) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.max(Math.hypot(dx, dy), 1);
  const headSize = Math.max(18, strokeWidth * 3.5);
  const shaft = new Line([0, 0, Math.max(length - headSize * 0.55, 1), 0], {
    stroke: color,
    strokeWidth,
    strokeLineCap: "round",
    originX: "left",
    originY: "center",
  });
  const head = new Triangle({
    width: headSize,
    height: headSize,
    fill: color,
    angle: 90,
    left: length - headSize / 2,
    top: 0,
    originX: "center",
    originY: "center",
  });
  const arrow = new Group([shaft, head], {
    left: start.x,
    top: start.y,
    angle: (Math.atan2(dy, dx) * 180) / Math.PI,
    originX: "left",
    originY: "center",
  });
  const editableArrow = ensureEditorMetadata(arrow, "arrow", "箭头") as Group & EditableFabricObject;
  editableArrow.setCoords();
  return editableArrow;
}

export function createEditorCommands(canvas: Canvas) {
  const selected = () => canvas.getActiveObjects().map(editable);

  const addObject = <T extends FabricObject>(
    object: T,
    type: EditableFabricObject["editorType"],
    name: string,
  ) => {
    const next = ensureEditorMetadata(object, type, name);
    canvas.add(next);
    canvas.centerObject(next);
    next.setCoords();
    canvas.setActiveObject(next);
    canvas.requestRenderAll();
    return next.id;
  };

  const mutateSelection = (mutation: (object: EditableFabricObject) => void) => {
    const objects = selected();
    if (objects.length === 0) return false;
    for (const object of objects) {
      mutation(object);
      object.setCoords();
    }
    canvas.requestRenderAll();
    return true;
  };

  return {
    addText(text = "双击编辑文本") {
      return addObject(
        new Textbox(text, {
          width: 360,
          fontSize: 48,
          fontFamily: "Geist Variable, sans-serif",
          fill: "#111111",
          textAlign: "center",
          originX: "center",
          originY: "center",
        }),
        "text",
        "文本",
      );
    },
    addRect() {
      return addObject(
        new Rect({
          width: 240,
          height: 160,
          fill: "#4b9eff",
          stroke: "transparent",
          originX: "center",
          originY: "center",
        }),
        "rect",
        "矩形",
      );
    },
    addEllipse() {
      return addObject(
        new Ellipse({
          rx: 120,
          ry: 80,
          fill: "#4b9eff",
          stroke: "transparent",
          originX: "center",
          originY: "center",
        }),
        "ellipse",
        "椭圆",
      );
    },
    addLine() {
      return addObject(
        new Line([-120, 0, 120, 0], {
          stroke: "#111111",
          strokeWidth: 4,
          originX: "center",
          originY: "center",
        }),
        "line",
        "直线",
      );
    },
    addArrow() {
      const arrow = createDirectionalArrow({ x: 380, y: 400 }, { x: 620, y: 400 });
      canvas.add(arrow);
      arrow.setCoords();
      canvas.setActiveObject(arrow);
      canvas.requestRenderAll();
      return arrow.id;
    },
    async duplicateSelection() {
      const objects = selected();
      if (objects.length === 0) return false;
      const clones = await Promise.all(objects.map((object) => object.clone()));
      for (let index = 0; index < clones.length; index += 1) {
        const source = objects[index];
        const clone = ensureEditorMetadata(
          clones[index],
          source.editorType,
          `${source.name} 副本`,
        );
        clone.set({
          left: (source.left ?? 0) + 20,
          top: (source.top ?? 0) + 20,
        });
        canvas.add(clone);
        clone.setCoords();
      }
      canvas.setActiveObject(clones[clones.length - 1]);
      canvas.requestRenderAll();
      return true;
    },
    deleteSelection() {
      const objects = selected();
      if (objects.length === 0) return false;
      canvas.remove(...objects);
      canvas.discardActiveObject();
      canvas.requestRenderAll();
      return true;
    },
    toggleLock() {
      return mutateSelection((object) => applyEditorLocked(object, !object.editorLocked));
    },
    toggleVisibility() {
      return mutateSelection((object) => object.set({ visible: object.visible === false }));
    },
    bringForward() {
      return mutateSelection((object) => {
        canvas.bringObjectForward(object);
      });
    },
    sendBackward() {
      return mutateSelection((object) => {
        canvas.sendObjectBackwards(object);
      });
    },
    bringToFront() {
      return mutateSelection((object) => {
        canvas.bringObjectToFront(object);
      });
    },
    sendToBack() {
      return mutateSelection((object) => {
        canvas.sendObjectToBack(object);
      });
    },
    alignHorizontalCenter() {
      return mutateSelection((object) => object.set({ left: canvas.getWidth() / 2 }));
    },
    alignVerticalCenter() {
      return mutateSelection((object) => object.set({ top: canvas.getHeight() / 2 }));
    },
    alignCenter() {
      return mutateSelection((object) => {
        canvas.centerObject(object);
      });
    },
  };
}

export type EditorCommands = ReturnType<typeof createEditorCommands>;

import {
  Circle,
  Group,
  Point,
  type Canvas,
  type FabricObject,
  type Path,
  util,
} from "fabric";
import type { EditableFabricObject } from "../utils/editorObject";

const HEX_COLOR = /^#([\da-f]{2})([\da-f]{2})([\da-f]{2})$/i;

export function colorWithOpacity(hex: string, opacity: number) {
  const match = HEX_COLOR.exec(hex);
  const alpha = Math.min(1, Math.max(0, opacity));
  if (!match) return hex;
  const [, red, green, blue] = match;
  return `rgba(${Number.parseInt(red, 16)},${Number.parseInt(green, 16)},${Number.parseInt(blue, 16)},${alpha})`;
}

function isDrawing(object: FabricObject): object is EditableFabricObject {
  return (object as EditableFabricObject).editorType === "drawing";
}

function createFilledEraserMask(eraserPath: Path) {
  const infos = util.getPathSegmentsInfo(eraserPath.path);
  const totalLength = infos[infos.length - 1]?.length ?? 0;
  const radius = Math.max((eraserPath.strokeWidth ?? 1) / 2, 0.5);
  const sampleCount = Math.min(512, Math.max(1, Math.ceil(totalLength / Math.max(radius, 1))));
  const transform = eraserPath.calcTransformMatrix();
  const circles = Array.from({ length: sampleCount + 1 }, (_, index) => {
    const distance = totalLength * (index / sampleCount);
    const pathPoint = util.getPointOnPath(eraserPath.path, distance, infos) ?? {
      x: eraserPath.pathOffset.x,
      y: eraserPath.pathOffset.y,
    };
    const canvasPoint = util.transformPoint(
      new Point(
        pathPoint.x - eraserPath.pathOffset.x,
        pathPoint.y - eraserPath.pathOffset.y,
      ),
      transform,
    );
    return new Circle({
      fill: "#000000",
      left: canvasPoint.x,
      top: canvasPoint.y,
      originX: "center",
      originY: "center",
      radius,
      strokeWidth: 0,
    });
  });
  return new Group(circles, {
    evented: false,
    inverted: true,
    selectable: false,
  });
}

export async function applyEraserStroke(canvas: Canvas, eraserPath: Path) {
  const drawings = canvas
    .getObjects()
    .filter(isDrawing)
    .filter((drawing) => drawing.intersectsWithObject(eraserPath));

  canvas.remove(eraserPath);
  if (drawings.length === 0) return false;

  await Promise.all(
    drawings.map(async (drawing) => {
      const mask = createFilledEraserMask(eraserPath);
      mask.absolutePositioned = true;
      const clipPath = drawing.clipPath
        ? util.mergeClipPaths(drawing.clipPath as never, mask as never)
        : mask;
      clipPath.absolutePositioned = true;
      drawing.clipPath = clipPath;
      drawing.dirty = true;
      drawing.setCoords();
    }),
  );
  canvas.requestRenderAll();
  return true;
}

import { FabricImage, type Canvas } from "fabric";
import { DEFAULT_MAX_IMAGE_SIZE } from "../ImageEditor.constants";
import { ImageEditorError } from "../ImageEditor.types";
import { ensureEditorMetadata, type EditableFabricObject } from "../utils/editorObject";
import { containSize, coverSize } from "../utils/geometry";

const IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/webp", "image/gif"]);

export function validateImageFile(file: File, maxSize = DEFAULT_MAX_IMAGE_SIZE) {
  if (!IMAGE_TYPES.has(file.type)) {
    throw new ImageEditorError("UNSUPPORTED_FILE", "不支持的图片格式");
  }
  if (file.size > maxSize) {
    const megabytes = Math.round(maxSize / 1024 / 1024);
    throw new ImageEditorError("FILE_TOO_LARGE", `图片不能超过 ${megabytes} MB`);
  }
}

export function fileToDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () =>
      reject(new ImageEditorError("IMAGE_DECODE_FAILED", "读取图片失败", reader.error));
    reader.readAsDataURL(file);
  });
}

export async function resolveImageSource(source: File | string, maxSize = DEFAULT_MAX_IMAGE_SIZE) {
  if (typeof source === "string") return source;
  validateImageFile(source, maxSize);
  return fileToDataUrl(source);
}

export async function addImageToCanvas(
  canvas: Canvas,
  source: File | string,
  maxSize = DEFAULT_MAX_IMAGE_SIZE,
) {
  const url = await resolveImageSource(source, maxSize);
  let image: FabricImage;
  try {
    image = await FabricImage.fromURL(url, { crossOrigin: "anonymous" });
  } catch (error) {
    throw new ImageEditorError(
      typeof source === "string" ? "IMAGE_CORS_FAILED" : "IMAGE_DECODE_FAILED",
      "图片加载失败",
      error,
    );
  }
  const editable = ensureEditorMetadata(image, "image", "图片");
  const size = containSize(
    { width: image.width || 1, height: image.height || 1 },
    { width: canvas.getWidth() * 0.8, height: canvas.getHeight() * 0.8 },
  );
  editable.set({ scaleX: size.scale, scaleY: size.scale });
  canvas.add(editable);
  canvas.centerObject(editable);
  editable.setCoords();
  canvas.setActiveObject(editable);
  canvas.requestRenderAll();
  return editable.id;
}

export function fitImageToCanvas(
  image: FabricImage,
  canvas: Pick<Canvas, "getWidth" | "getHeight" | "centerObject">,
  mode: "contain" | "cover",
) {
  const calculator = mode === "contain" ? containSize : coverSize;
  const size = calculator(
    { width: image.width || 1, height: image.height || 1 },
    { width: canvas.getWidth(), height: canvas.getHeight() },
  );
  image.set({ scaleX: size.scale, scaleY: size.scale });
  canvas.centerObject?.(image);
  image.setCoords();
}

export function flipImage(image: FabricImage, axis: "x" | "y") {
  image.set(axis === "x" ? { flipX: !image.flipX } : { flipY: !image.flipY });
  image.setCoords();
}

export async function replaceImageSource(image: FabricImage, source: File | string, maxSize?: number) {
  const url = await resolveImageSource(source, maxSize);
  const replacement = await FabricImage.fromURL(url, { crossOrigin: "anonymous" });
  const displayedWidth = image.getScaledWidth();
  const displayedHeight = image.getScaledHeight();
  image.setElement(replacement.getElement());
  image.set({
    width: replacement.width,
    height: replacement.height,
    cropX: 0,
    cropY: 0,
    scaleX: displayedWidth / Math.max(1, replacement.width),
    scaleY: displayedHeight / Math.max(1, replacement.height),
  });
  image.setCoords();
  return image as FabricImage & EditableFabricObject;
}

import type { FabricImage } from "fabric";

type CropSnapshot = Pick<
  FabricImage,
  "cropX" | "cropY" | "width" | "height" | "scaleX" | "scaleY" | "left" | "top"
>;

function snapshot(image: FabricImage): CropSnapshot {
  return {
    cropX: image.cropX,
    cropY: image.cropY,
    width: image.width,
    height: image.height,
    scaleX: image.scaleX,
    scaleY: image.scaleY,
    left: image.left,
    top: image.top,
  };
}

export class CropSession {
  private readonly initial: CropSnapshot;
  private finished = false;

  private constructor(private readonly image: FabricImage) {
    this.initial = snapshot(image);
  }

  static start(image: FabricImage) {
    return new CropSession(image);
  }

  pan(deltaX: number, deltaY: number) {
    if (this.finished) return;
    const element = this.image.getElement() as HTMLImageElement;
    const sourceWidth = element.naturalWidth || element.width;
    const sourceHeight = element.naturalHeight || element.height;
    this.image.set({
      cropX: Math.min(Math.max(0, this.image.cropX + deltaX), Math.max(0, sourceWidth - this.image.width)),
      cropY: Math.min(Math.max(0, this.image.cropY + deltaY), Math.max(0, sourceHeight - this.image.height)),
    });
    this.image.setCoords();
  }

  zoom(factor: number) {
    if (this.finished || !Number.isFinite(factor) || factor <= 0) return;
    const element = this.image.getElement() as HTMLImageElement;
    const sourceWidth = element.naturalWidth || element.width;
    const sourceHeight = element.naturalHeight || element.height;
    this.image.set({
      width: Math.min(sourceWidth, Math.max(1, this.initial.width / factor)),
      height: Math.min(sourceHeight, Math.max(1, this.initial.height / factor)),
    });
    this.pan(0, 0);
  }

  cancel() {
    if (this.finished) return;
    this.image.set(this.initial);
    this.image.setCoords();
    this.finished = true;
  }

  confirm() {
    if (this.finished) return { changed: false };
    const changed = JSON.stringify(snapshot(this.image)) !== JSON.stringify(this.initial);
    this.finished = true;
    return { changed };
  }
}

import type { Canvas } from "fabric";
import { ImageEditorError, type ExportOptions, type ImageEditorDocument } from "../ImageEditor.types";

export async function exportCanvas(
  canvas: Canvas,
  document: ImageEditorDocument,
  options: ExportOptions = {},
): Promise<Blob> {
  const format = options.format ?? "png";
  const quality = Math.min(1, Math.max(0, options.quality ?? 1));
  const multiplier = options.width
    ? options.width / document.canvas.width
    : options.height
      ? options.height / document.canvas.height
      : 1;
  const active = canvas.getActiveObject();
  const background = canvas.backgroundColor;

  try {
    canvas.discardActiveObject();
    if (format === "png" && options.transparent) {
      canvas.backgroundColor = "rgba(0,0,0,0)";
    } else if (format === "jpeg" && document.canvas.background === null) {
      canvas.backgroundColor = "#ffffff";
    }
    canvas.requestRenderAll();
    const dataUrl = canvas.toDataURL({ format, quality, multiplier });
    const response = await fetch(dataUrl);
    if (!response.ok) throw new Error(`Export response ${response.status}`);
    return await response.blob();
  } catch (error) {
    if (error instanceof DOMException && error.name === "SecurityError") {
      throw new ImageEditorError("EXPORT_CORS_FAILED", "跨域图片导致画布无法导出", error);
    }
    if (error instanceof ImageEditorError) throw error;
    throw new ImageEditorError("EXPORT_FAILED", "图片导出失败", error);
  } finally {
    canvas.backgroundColor = background;
    if (active) canvas.setActiveObject(active);
    canvas.requestRenderAll();
  }
}

export function downloadBlob(blob: Blob, fileName: string) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  URL.revokeObjectURL(url);
}

import type { Size } from "../utils/geometry";

export type Bounds = {
  left: number;
  top: number;
  width: number;
  height: number;
};

export type SnapResult = {
  left: number;
  top: number;
  verticalGuide?: number;
  horizontalGuide?: number;
};

function axisPoints(start: number, size: number) {
  return [start + size / 2, start, start + size];
}

function findOffset(moving: number[], targets: number[], threshold: number) {
  for (const target of targets) {
    for (const point of moving) {
      const difference = target - point;
      if (Math.abs(difference) <= threshold) return { difference, guide: target };
    }
  }
  return null;
}

export function calculateSnapPosition(
  moving: Bounds,
  others: Bounds[],
  canvas: Size,
  threshold: number,
  disabled = false,
): SnapResult {
  if (disabled) return { left: moving.left, top: moving.top };
  const xTargets = [canvas.width / 2];
  const yTargets = [canvas.height / 2];
  for (const other of others) {
    const x = axisPoints(other.left, other.width);
    const y = axisPoints(other.top, other.height);
    xTargets.push(x[0], x[1], x[2]);
    yTargets.push(y[0], y[1], y[2]);
  }
  const xSnap = findOffset(axisPoints(moving.left, moving.width), xTargets, threshold);
  const ySnap = findOffset(axisPoints(moving.top, moving.height), yTargets, threshold);
  return {
    left: moving.left + (xSnap?.difference ?? 0),
    top: moving.top + (ySnap?.difference ?? 0),
    ...(xSnap ? { verticalGuide: xSnap.guide } : {}),
    ...(ySnap ? { horizontalGuide: ySnap.guide } : {}),
  };
}

import { Canvas, FabricObject } from "fabric";
import { useCallback, useEffect, useRef, useState } from "react";
import { clampZoom, editorFitPadding, fitViewport, type Size } from "../utils/geometry";

let defaultsConfigured = false;

export function useFabricCanvas(documentSize: Size) {
  const viewportRef = useRef<HTMLDivElement>(null);
  const canvasElementRef = useRef<HTMLCanvasElement>(null);
  const canvasRef = useRef<Canvas | null>(null);
  const [canvas, setCanvas] = useState<Canvas | null>(null);
  const [zoom, setZoomState] = useState(1);

  const setZoom = useCallback((value: number) => {
    setZoomState(clampZoom(value));
  }, []);

  const fitToViewport = useCallback(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const bounds = viewport.getBoundingClientRect();
    setZoomState(fitViewport(bounds, documentSize, editorFitPadding(bounds.height)));
  }, [documentSize.height, documentSize.width]);

  useEffect(() => {
    const element = canvasElementRef.current;
    if (!element || canvasRef.current) return;
    if (!defaultsConfigured) {
      FabricObject.ownDefaults.transparentCorners = false;
      defaultsConfigured = true;
    }
    const instance = new Canvas(element, {
      preserveObjectStacking: true,
      selection: true,
      enableRetinaScaling: true,
    });
    instance.setDimensions(documentSize);
    canvasRef.current = instance;
    setCanvas(instance);

    return () => {
      canvasRef.current = null;
      void instance.dispose();
    };
  }, []);

  useEffect(() => {
    const instance = canvasRef.current;
    if (!instance) return;
    instance.setDimensions(documentSize);
    instance.requestRenderAll();
    fitToViewport();
  }, [documentSize.height, documentSize.width, fitToViewport]);

  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const observer = new ResizeObserver(fitToViewport);
    observer.observe(viewport);
    const handleWheel = (event: WheelEvent) => {
      if (!(event.ctrlKey || event.metaKey)) return;
      event.preventDefault();
      setZoomState((current) => clampZoom(current * Math.exp(-event.deltaY * 0.0015)));
    };
    viewport.addEventListener("wheel", handleWheel, { passive: false });
    fitToViewport();
    return () => {
      observer.disconnect();
      viewport.removeEventListener("wheel", handleWheel);
    };
  }, [fitToViewport]);

  return {
    canvas,
    canvasElementRef,
    viewportRef,
    zoom,
    setZoom,
    fitToViewport,
  };
}

